namespace Turian.Editor.Core;

/// <summary>
/// A single entry in the user-code type manifest: one class with its stable TypeId.
/// </summary>
public sealed class UserCodeTypeEntry
{
    /// <summary>Fully-qualified class name, e.g. "Usercode.TranslateComponent".</summary>
    public string FullyQualifiedName { get; init; } = string.Empty;

    /// <summary>Stable TypeId sourced from the companion .cs.meta AssetId.</summary>
    public Guid TypeId { get; init; }
}

/// <summary>
/// Persisted mapping from user-defined class names to their stable AssetId-based TypeIds.
/// Generated by <see cref="UserCodeTypeManifestGenerator"/> after each successful compilation
/// and placed next to the compiled DLL as <c>usercode.typeids.json</c>.
/// At runtime the manifest is loaded by <see cref="RegisterFromManifest"/> so that user types
/// are registered in <see cref="TypeRegistry"/> without needing a <c>[TypeId]</c> attribute.
/// </summary>
public sealed class UserCodeTypeManifest
{
    static readonly JsonSerializerOptions jsonOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>File name used when persisting the manifest alongside the compiled DLL.</summary>
    public const string FileName = "usercode.typeids.json";

    /// <summary>Name of the user assembly, which a runtime loads before resolving <see cref="Types"/>.</summary>
    public string? AssemblyName { get; init; }

    /// <summary>Registered type entries.</summary>
    public List<UserCodeTypeEntry> Types { get; init; } = [];

    /// <summary>Returns the manifest file path for the given assembly file path.</summary>
    public static string ManifestPathFor(string assemblyPath) =>
        Path.Combine(Path.GetDirectoryName(assemblyPath)!, FileName);

    /// <summary>Returns true if the manifest file exists next to the given assembly.</summary>
    public static bool Exists(string assemblyPath) =>
        File.Exists(ManifestPathFor(assemblyPath));

    /// <summary>Serializes and writes the manifest next to the assembly DLL.</summary>
    public static void Save(UserCodeTypeManifest manifest, string assemblyPath)
    {
        var path = ManifestPathFor(assemblyPath);
        File.WriteAllText(path, JsonSerializer.Serialize(manifest, jsonOptions));
    }

    /// <summary>
    /// Loads the manifest from disk and registers each entry into <see cref="TypeRegistry"/>.
    /// Types not found in <paramref name="userAssembly"/> are skipped with a warning.
    /// </summary>
    public static void RegisterFromManifest(string assemblyPath, ReflectionAssembly userAssembly, ILogger logger)
    {
        ArgumentNullException.ThrowIfNull(userAssembly);
        ArgumentNullException.ThrowIfNull(logger);

        var path = ManifestPathFor(assemblyPath);
        if (!File.Exists(path))
        {
            logger.LogWarning("User-code type manifest not found at {Path}. User-defined types will not be polymorphically serializable", path);
            return;
        }

        UserCodeTypeManifest? manifest;
        try
        {
            manifest = JsonSerializer.Deserialize<UserCodeTypeManifest>(File.ReadAllText(path), jsonOptions);
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Failed to parse user-code type manifest at {Path}", path);
            return;
        }

        if (manifest is null)
            return;

        var registered = 0;
        foreach (var entry in manifest.Types)
        {
            var type = userAssembly.GetType(entry.FullyQualifiedName);
            if (type is null)
            {
                logger.LogWarning("User type '{Fqn}' not found in assembly; skipping registration", entry.FullyQualifiedName);
                continue;
            }

            TypeRegistry.Register(entry.TypeId, type);
            registered++;
        }

        logger.LogInformation("Registered {Count}/{Total} user type(s) from manifest", registered, manifest.Types.Count);
    }
}
